insert into public.lessons (slug, position, level, track, title, summary, steps) values ('intro', 1, 1, 'basics', '{"az":"Qo oyununa giriş","en":"Introduction to Go","ru":"Введение в го"}'::jsonb, '{"az":"Qo nədir və məqsəd nədir?","en":"What is Go and what is the goal?","ru":"Что такое го и в чём цель?"}'::jsonb, '[{"text":{"az":"Qo (Baduk, Weiqi) 4000 ildən çox yaşı olan strateji oyundur. İki oyunçu növbə ilə qara və ağ daşlar qoyur. Məqsəd taxtanın daha çox hissəsini — ərazini — əhatə etməkdir.","en":"Go (Baduk, Weiqi) is a strategy game more than 4,000 years old. Two players take turns placing black and white stones. The goal is to surround more of the board — territory — than your opponent.","ru":"Го (бадук, вэйци) — стратегическая игра возрастом более 4000 лет. Два игрока по очереди ставят чёрные и белые камни. Цель — окружить больше территории, чем соперник."}},{"text":{"az":"Qaydalar sadədir: qara birinci gedir, daşlar xətlərin kəsişməsinə qoyulur və qoyulduqdan sonra yerindən tərpənmir. Sınaqdan keçirin — istənilən kəsişməyə daş qoyun.","en":"The rules are simple: Black goes first, stones go on the intersections of the lines and never move once placed. Try it — place a stone on any intersection.","ru":"Правила просты: чёрные ходят первыми, камни ставятся на пересечения линий и после этого не двигаются. Попробуйте — поставьте камень на любое пересечение."},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"any"},"success":{"az":"Əla! İlk daşınızı qoydunuz.","en":"Great! You placed your first stone.","ru":"Отлично! Вы поставили первый камень."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('board-stones', 2, 1, 'basics', '{"az":"Taxta və daşlar","en":"The board and stones","ru":"Доска и камни"}'::jsonb, '{"az":"9×9, 13×13 və 19×19 taxtalar.","en":"9×9, 13×13 and 19×19 boards.","ru":"Доски 9×9, 13×13 и 19×19."}'::jsonb, '[{"text":{"az":"Oyun 19×19 taxtada oynanır, amma başlamaq üçün 9×9 və 13×13 daha yaxşıdır. Daşlar xətlərin kəsişməsində dayanır. Kiçik qara nöqtələr (hoşi) istiqamət tapmağa kömək edir.","en":"The standard board is 19×19, but 9×9 and 13×13 are better for learning. Stones sit on the intersections. The small dots (star points) help you find your way.","ru":"Стандартная доска — 19×19, но для обучения лучше 9×9 и 13×13. Камни стоят на пересечениях. Маленькие точки (хоси) помогают ориентироваться."}},{"text":{"az":"Qo-da kim birinci gedir?","en":"Who plays first in Go?","ru":"Кто ходит первым в го?"},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Qo-da kim birinci gedir?","en":"Who plays first in Go?","ru":"Кто ходит первым в го?"},"options":[{"az":"Qara","en":"Black","ru":"Чёрные"},{"az":"Ağ","en":"White","ru":"Белые"}],"correct":0},"success":{"az":"Düzdür — qara birinci gedir. Ağ kompensasiya kimi komi alır.","en":"Correct — Black moves first. White receives komi as compensation.","ru":"Верно — чёрные ходят первыми. Белые получают коми в качестве компенсации."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('liberties', 3, 1, 'basics', '{"az":"Azadlıqlar","en":"Liberties","ru":"Дамэ (свободы)"}'::jsonb, '{"az":"Daşın \"nəfəs\" aldığı boş nöqtələr.","en":"The empty points a stone \"breathes\" through.","ru":"Пустые пункты, которыми камень «дышит»."}'::jsonb, '[{"text":{"az":"Daşın azadlığı — ona xətt boyunca bitişik boş nöqtədir. Ortadakı daşın 4 azadlığı var (işarələnib). Kənardakının 3, küncdəkinin isə yalnız 2 azadlığı var.","en":"A stone’s liberties are the empty points directly next to it along the lines. A stone in the middle has 4 liberties (marked). On an edge it has 3 and in a corner only 2.","ru":"Свободы камня — пустые пункты, соседние с ним по линиям. У камня в центре 4 свободы (отмечены). На краю — 3, в углу — всего 2."},"exercise":{"size":9,"rows":["X........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Küncdəki daşın neçə azadlığı var?","en":"How many liberties does a corner stone have?","ru":"Сколько свобод у камня в углу?"},"options":[{"az":"2","en":"2","ru":"2"},{"az":"3","en":"3","ru":"3"},{"az":"4","en":"4","ru":"4"}],"correct":0},"marks":[1,9],"success":{"az":"Düzdür: küncdə yalnız 2 azadlıq.","en":"Right: only 2 in a corner.","ru":"Верно: в углу только 2."}}},{"text":{"az":"Ortadakı daşa baxın.","en":"Look at the stone in the middle.","ru":"Посмотрите на камень в центре."},"exercise":{"size":9,"rows":[".........",".........",".........",".........","....X....",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Ortadakı daşın neçə azadlığı var?","en":"How many liberties does the centre stone have?","ru":"Сколько свобод у камня в центре?"},"options":[{"az":"2","en":"2","ru":"2"},{"az":"3","en":"3","ru":"3"},{"az":"4","en":"4","ru":"4"}],"correct":2},"marks":[39,41,31,49],"success":{"az":"Düzdür: 4 azadlıq.","en":"Right: 4 liberties.","ru":"Верно: 4 свободы."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('capturing', 4, 1, 'basics', '{"az":"Daşları tutmaq","en":"Capturing stones","ru":"Взятие камней"}'::jsonb, '{"az":"Azadlığı qalmayan daş tutulur.","en":"A stone with no liberties is captured.","ru":"Камень без свобод снимается с доски."}'::jsonb, '[{"text":{"az":"Rəqibin daşının son azadlığını doldursanız, o daş tutulur və taxtadan götürülür. Ağ daşın yalnız bir azadlığı qalıb — onu tutun.","en":"If you fill the last liberty of an enemy stone, it is captured and removed from the board. The white stone has just one liberty left — capture it.","ru":"Если вы занимаете последнюю свободу камня противника, он берётся и снимается с доски. У белого камня осталась одна свобода — возьмите его."},"exercise":{"size":9,"rows":[".........",".........",".........","....X....","...XOX...",".........",".........",".........","........."],"goal":{"type":"capture"},"hint":{"az":"Ağ daşın altındakı boş nöqtəyə baxın.","en":"Look at the empty point below the white stone.","ru":"Посмотрите на пустой пункт под белым камнем."},"success":{"az":"Tutdunuz! Daş götürüldü.","en":"Captured! The stone is removed.","ru":"Взято! Камень снят."}}},{"text":{"az":"Kənarda daşları tutmaq daha asandır — daha az azadlıq var.","en":"Capturing is easier on the edge — fewer liberties.","ru":"На краю брать проще — свобод меньше."},"exercise":{"size":9,"rows":["OX.......",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"capture"},"hint":{"az":"Ağ daş küncdədir.","en":"The white stone is in the corner.","ru":"Белый камень в углу."},"success":{"az":"Əla!","en":"Well done!","ru":"Отлично!"}}},{"text":{"az":"İki daşdan ibarət qrupu da tutmaq olar. Son azadlığı tapın.","en":"You can capture a group of two stones too. Find the last liberty.","ru":"Можно взять и группу из двух камней. Найдите последнюю свободу."},"exercise":{"size":9,"rows":["..XOO....","...XX....",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"capture","min":2},"hint":{"az":"Qrupun sağında.","en":"To the right of the group.","ru":"Справа от группы."},"success":{"az":"İki daş birdən tutuldu!","en":"Two stones captured at once!","ru":"Два камня взяты сразу!"}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('groups', 5, 2, 'basics', '{"az":"Qruplar","en":"Groups and connection","ru":"Группы и связь"}'::jsonb, '{"az":"Bitişik daşlar bir qrup yaradır.","en":"Adjacent stones form a group.","ru":"Соседние камни образуют группу."}'::jsonb, '[{"text":{"az":"Xətt boyunca bitişik eyni rəngli daşlar bir qrupdur: onlar azadlıqları paylaşır və birlikdə tutulur. Çəp qonşu daşlar bağlı deyil.","en":"Same-coloured stones next to each other along a line form a group: they share liberties and are captured together. Diagonal neighbours are NOT connected.","ru":"Камни одного цвета, соседние по линии, образуют группу: у них общие свободы, и берутся они вместе. Диагональные соседи НЕ связаны."},"exercise":{"size":9,"rows":[".........",".........",".........","...X.....","....X....",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Çəp yerləşən iki daş bir qrupdur?","en":"Are two diagonally placed stones one group?","ru":"Образуют ли два диагональных камня одну группу?"},"options":[{"az":"Bəli","en":"Yes","ru":"Да"},{"az":"Xeyr","en":"No","ru":"Нет"}],"correct":1},"success":{"az":"Xeyr, bağlı deyillər.","en":"No — they are not connected.","ru":"Нет, они не связаны."}}},{"text":{"az":"Rəqib iki daşınızı ayıra bilər. Onları bağlayın!","en":"The opponent can cut your two stones apart. Connect them!","ru":"Соперник может разрезать ваши камни. Соедините их!"},"exercise":{"size":9,"rows":[".........",".........",".........","....O....","...X.X...","....O....",".........",".........","........."],"goal":{"type":"point","points":[40]},"hint":{"az":"İki qara daşın arasındakı nöqtə.","en":"The point between the two black stones.","ru":"Пункт между двумя чёрными камнями."},"success":{"az":"Bağlandı — indi bir qrupdur.","en":"Connected — now they are one group.","ru":"Соединено — теперь это одна группа."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('ko', 6, 2, 'basics', '{"az":"Ko qaydası","en":"The ko rule","ru":"Правило ко"}'::jsonb, '{"az":"Sonsuz təkrarın qarşısını alır.","en":"It prevents endless repetition.","ru":"Предотвращает бесконечные повторы."}'::jsonb, '[{"text":{"az":"Bəzən iki tərəf bir daşı sonsuz tuta bilər. Bunun qarşısını ko qaydası alır: tutulan daşı dərhal geri tutmaq olmaz — əvvəlcə başqa yerdə gediş (ko təhdidi) etmək lazımdır. Qara indi daşı tuta bilər:","en":"Sometimes both sides could capture the same stone forever. The ko rule stops this: you may not immediately recapture — you must first play elsewhere (a ko threat). Black can capture now:","ru":"Иногда стороны могли бы бесконечно брать один и тот же камень. Правило ко это запрещает: нельзя сразу брать обратно — сначала нужно сделать ход в другом месте (угроза ко). Чёрные могут взять сейчас:"},"exercise":{"size":9,"rows":[".XO......","XO.O.....",".XO......",".........",".........",".........",".........",".........","........."],"goal":{"type":"capture"},"hint":{"az":"Ağ daşın sağındakı boş nöqtə.","en":"The empty point to the right of the white stone.","ru":"Пустой пункт справа от белого камня."}}},{"text":{"az":"İndi ağın növbəsidir.","en":"Now it is White’s turn.","ru":"Теперь ход белых."},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Ağ tutulan yerə dərhal qayıda bilər?","en":"May White immediately retake in the same spot?","ru":"Могут ли белые сразу взять обратно на том же месте?"},"options":[{"az":"Bəli","en":"Yes","ru":"Да"},{"az":"Xeyr","en":"No","ru":"Нет"}],"correct":1},"success":{"az":"Xeyr — bu ko-dur. Əvvəlcə ko təhdidi lazımdır.","en":"No — that is ko. A ko threat is needed first.","ru":"Нет — это ко. Сначала нужна угроза ко."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('territory', 7, 2, 'basics', '{"az":"Ərazi və hesablama","en":"Territory and scoring","ru":"Территория и подсчёт"}'::jsonb, '{"az":"Oyun necə sona çatır və qalib kim olur.","en":"How a game ends and who wins.","ru":"Как заканчивается игра и кто побеждает."}'::jsonb, '[{"text":{"az":"Hər iki oyunçu pas dedikdə oyun bitir. Ərazi — yalnız bir rəngin əhatə etdiyi boş nöqtələrdir. Yapon qaydasında ərazi + əsirlər, Çin qaydasında ərazi + taxtadakı daşlar sayılır. Ağa komi əlavə olunur.","en":"The game ends when both players pass. Territory is the empty points surrounded by one colour only. Japanese rules count territory + prisoners, Chinese rules count territory + stones on the board. White gets komi added.","ru":"Игра заканчивается, когда оба игрока пасуют. Территория — пустые пункты, окружённые одним цветом. По японским правилам считают территорию + пленных, по китайским — территорию + камни на доске. Белым добавляется коми."},"exercise":{"size":9,"rows":["...X.O...","...X.O...","...X.O...","...X.O...","...X.O...","...X.O...","...X.O...","...X.O...","...X.O..."],"goal":{"type":"quiz","question":{"az":"Qara neçə xal ərazi qazanıb?","en":"How many points of territory does Black own?","ru":"Сколько пунктов территории у чёрных?"},"options":[{"az":"18","en":"18","ru":"18"},{"az":"27","en":"27","ru":"27"},{"az":"36","en":"36","ru":"36"}],"correct":1},"success":{"az":"Sol tərəfdə 3×9 = 27 boş nöqtə. Ortadakı sütun heç kimin deyil.","en":"3×9 = 27 empty points on the left. The middle column belongs to nobody.","ru":"Слева 3×9 = 27 пустых пунктов. Средний столбец ничей."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('life-death', 8, 3, 'basics', '{"az":"Həyat və ölüm","en":"Life and death","ru":"Жизнь и смерть"}'::jsonb, '{"az":"İki göz — qrupun ölməzliyi.","en":"Two eyes — a group that cannot be killed.","ru":"Два глаза — группа, которую нельзя убить."}'::jsonb, '[{"text":{"az":"Qrup iki \"göz\"ə (ayrı-ayrı əhatə olunmuş boş nöqtələr) malikdirsə, rəqib ona heç vaxt hücum edib tuta bilməz — çünki gözləri doldurmaq intiharçılıqdır. Bu, qrupun \"diri\" olması deməkdir.","en":"If a group has two \"eyes\" (separate surrounded empty points) the opponent can never capture it — filling an eye would be suicide. Such a group is \"alive\".","ru":"Если у группы два «глаза» (отдельных окружённых пустых пункта), противник никогда не сможет её взять — заполнение глаза было бы самоубийством. Такая группа «жива»."},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Qrupun yaşaması üçün neçə göz lazımdır?","en":"How many eyes does a group need to live?","ru":"Сколько глаз нужно группе, чтобы жить?"},"options":[{"az":"1","en":"1","ru":"1"},{"az":"2","en":"2","ru":"2"},{"az":"3","en":"3","ru":"3"}],"correct":1}}},{"text":{"az":"Üç boş nöqtənin yan-yana olduğu bu formada \"həyati nöqtə\" ortadadır. Qara oynayır — iki göz yaradın!","en":"In this shape of three empty points in a row, the vital point is the middle one. Black to play — make two eyes!","ru":"В этой форме с тремя пустыми пунктами в ряд жизненно важный пункт — средний. Ход чёрных — создайте два глаза!"},"exercise":{"size":9,"rows":["X...X....","XXXXX....",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"point","points":[2]},"hint":{"az":"Üç boş nöqtənin ortası.","en":"The middle of the three empty points.","ru":"Середина трёх пустых пунктов."},"success":{"az":"Düzdür! İndi iki ayrı gözünüz var: qrup diridir.","en":"Correct! Now you have two separate eyes: the group lives.","ru":"Верно! Теперь у вас два отдельных глаза: группа жива."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('opening', 9, 3, 'basics', '{"az":"Açılış strategiyası","en":"Opening strategy","ru":"Стратегия дебюта"}'::jsonb, '{"az":"Künclər, kənarlar, mərkəz.","en":"Corners, sides, centre.","ru":"Углы, стороны, центр."}'::jsonb, '[{"text":{"az":"Qaydası: künc → kənar → mərkəz. Künclərdə az daşla çox ərazi əhatə etmək olar, ona görə açılış adətən künclərdən başlayır.","en":"The rule of thumb: corners → sides → centre. In corners you can claim territory with few stones, so openings usually start there.","ru":"Правило: углы → стороны → центр. В углах можно занять территорию малым числом камней, поэтому дебют обычно начинается с них."},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"quiz","question":{"az":"Açılışda adətən haradan başlanır?","en":"Where do openings usually start?","ru":"С чего обычно начинается дебют?"},"options":[{"az":"Mərkəz","en":"The centre","ru":"Центр"},{"az":"Künclər","en":"The corners","ru":"Углы"},{"az":"Kənarın ortası","en":"Middle of a side","ru":"Середина стороны"}],"correct":1}}},{"text":{"az":"Boş 9×9 taxtada qara kimi künc nöqtəsinə daş qoyun.","en":"On an empty 9×9 board, play a corner point as Black.","ru":"На пустой доске 9×9 поставьте камень в угловой пункт."},"exercise":{"size":9,"rows":[".........",".........",".........",".........",".........",".........",".........",".........","........."],"goal":{"type":"point","points":[20,24,56,60,29,21,23,33,47,57,59,51]},"hint":{"az":"Kənardan 3-cü xətdəki hoşi nöqtələrə baxın.","en":"Look at the star points on the third line.","ru":"Посмотрите на пункты хоси на третьей линии."},"success":{"az":"Yaxşı açılış!","en":"A good opening move!","ru":"Хороший дебютный ход!"}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('tactics', 10, 3, 'basics', '{"az":"Başlanğıc taktikası","en":"Beginner tactics","ru":"Базовая тактика"}'::jsonb, '{"az":"Atari, qaçış və tutma.","en":"Atari, escaping and capturing races.","ru":"Атари, побег и взятие."}'::jsonb, '[{"text":{"az":"\"Atari\" — daşın yalnız bir azadlığının qalması deməkdir. Növbəti gedişdə tutula bilər. Ağ daşı atariyə salın!","en":"\"Atari\" means a stone has only one liberty left and can be captured next move. Put the white stone in atari!","ru":"«Атари» значит, что у камня осталась одна свобода, и в следующий ход его можно взять. Поставьте белый камень в атари!"},"exercise":{"size":9,"rows":[".........",".........",".........","....X....","...XO....",".........",".........",".........","........."],"goal":{"type":"point","points":[41,49]},"hint":{"az":"Ağ daşın qalan iki azadlığından birini tutun.","en":"Take one of the two remaining liberties.","ru":"Займите одну из двух оставшихся свобод."},"success":{"az":"Atari! Ağ daş indi bir azadlıqla qalıb.","en":"Atari! The stone is down to one liberty.","ru":"Атари! У камня осталась одна свобода."}}},{"text":{"az":"İndi sizin daşınız atari vəziyyətindədir. Qaçın — azadlıqlarınızı artırın!","en":"Now YOUR stone is in atari. Escape — gain liberties!","ru":"Теперь в атари ВАШ камень. Убегайте — добавьте свободы!"},"exercise":{"size":9,"rows":[".........",".........",".........","....O....","...OXO...",".........",".........",".........","........."],"goal":{"type":"point","points":[49]},"hint":{"az":"Qara daşın yeganə azadlığına uzadın.","en":"Extend into the stone’s only liberty.","ru":"Продлите камень на его единственную свободу."},"success":{"az":"Qaçdınız — indi 3 azadlıq var.","en":"Escaped — now it has 3 liberties.","ru":"Убежали — теперь три свободы."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('open-principles', 101, 2, 'openings', '{"az":"Açılışın əsas prinsipləri","en":"Opening principles","ru":"Принципы дебюта"}'::jsonb, '{"az":"Künc → kənar → mərkəz.","en":"Corner → side → centre.","ru":"Угол → сторона → центр."}'::jsonb, '[{"text":{"az":"Qo-da açılışa \"fuseki\" deyilir. Taxtanın künclərində az daşla ərazini əldə etmək asandır, kənarlarda çətinləşir, mərkəzdə ən çətindir. Buna görə adətən əvvəl künclər, sonra kənarlar, ən axırda mərkəz tutulur.","en":"The opening is called \"fuseki\". Territory is easiest to secure in the corners with few stones, harder along the sides and hardest in the centre — so players usually take corners first, then sides, then the centre.","ru":"Дебют в го называется «фусэки». В углах территорию проще всего занять малым числом камней, на сторонах сложнее, в центре сложнее всего — поэтому обычно сначала занимают углы, затем стороны и в последнюю очередь центр."},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"quiz","question":{"az":"Hansı sıra daha səmərəlidir?","en":"Which order is usually more efficient?","ru":"Какой порядок обычно эффективнее?"},"options":[{"az":"Mərkəz → kənar → künc","en":"Centre → side → corner","ru":"Центр → сторона → угол"},{"az":"Künc → kənar → mərkəz","en":"Corner → side → centre","ru":"Угол → сторона → центр"}],"correct":1}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('open-corner-points', 102, 2, 'openings', '{"az":"Künc nöqtələri: 3-3, 3-4, 4-4","en":"Corner points: 3-3, 3-4, 4-4","ru":"Угловые пункты: 3-3, 3-4, 4-4"}'::jsonb, '{"az":"Xətt nömrələri ilə künc nöqtələri.","en":"Corner points named by line numbers.","ru":"Угловые пункты по номерам линий."}'::jsonb, '[{"text":{"az":"Künc nöqtələri kənardan sayılan xətt nömrələri ilə adlanır. 4-4 (hoşi, ulduz) — hər iki istiqamətdə 4-cü xətt: ərazi və təsir arasında tarazlıq. 3-4 (komoku) — bir istiqamətdə 3-cü, digərində 4-cü xətt. 3-3 (sansan) — ərazini sürətlə təmin edir. Yuxarı sağ küncdə 4-4 nöqtəsini seçin:","en":"Corner points are named by their distance from the edges. The 4-4 point (hoshi, \"star\") is on the 4th line both ways — a balance of territory and influence. The 3-4 point (komoku) is on the 3rd line one way and the 4th the other. The 3-3 point (sansan) secures territory quickly. Play the 4-4 point in the top-right corner:","ru":"Угловые пункты называют по удалённости от краёв. 4-4 (хоси, «звезда») — 4-я линия в обоих направлениях: баланс территории и влияния. 3-4 (комоку) — 3-я линия в одном направлении и 4-я в другом. 3-3 (сансан) быстро обеспечивает территорию. Поставьте камень в пункт 4-4 в правом верхнем углу:"},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"point","points":[72]},"hint":{"az":"Yuxarı və sağ kənardan 4-cü xətt.","en":"4th line from the top and from the right.","ru":"4-я линия сверху и справа."},"success":{"az":"Bu 4-4 nöqtəsidir (hoşi).","en":"That is the 4-4 point (hoshi).","ru":"Это пункт 4-4 (хоси)."}}},{"text":{"az":"İndi 3-3 nöqtəsini seçin (yuxarı sağ künc).","en":"Now play the 3-3 point (top-right corner).","ru":"Теперь выберите пункт 3-3 (правый верхний угол)."},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"point","points":[54]},"hint":{"az":"Hər iki kənardan 3-cü xətt.","en":"3rd line from both edges.","ru":"3-я линия от обоих краёв."},"success":{"az":"Bu 3-3 nöqtəsidir (sansan).","en":"That is the 3-3 point (sansan).","ru":"Это пункт 3-3 (сансан)."}}},{"text":{"az":"Sonda 3-4 nöqtəsi: iki variant doğrudur (ikisi də 3-4).","en":"Finally the 3-4 point: both orientations are correct.","ru":"Наконец, пункт 3-4: верны обе ориентации."},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"point","points":[73,53]},"hint":{"az":"Bir tərəfdən 3-cü, digərindən 4-cü xətt.","en":"3rd line one way, 4th the other.","ru":"3-я линия в одну сторону, 4-я в другую."},"success":{"az":"Bu 3-4 nöqtəsidir (komoku).","en":"That is the 3-4 point (komoku).","ru":"Это пункт 3-4 (комоку)."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('open-sanrensei', 103, 2, 'openings', '{"az":"Sanrensei (üç ulduz)","en":"Sanrensei (three stars)","ru":"Санрэнсэй (три звезды)"}'::jsonb, '{"az":"Bir kənarda üç hoşi nöqtəsi.","en":"Three star points along one side.","ru":"Три звёздные точки вдоль одной стороны."}'::jsonb, '[{"text":{"az":"Sanrensei — bir kənar boyunca üç ulduz nöqtəsinin tutulmasıdır: iki künc ulduzu və aralarındakı kənar ulduzu. Məqsəd — həmin kənarda böyük təsir və potensial ərazi qurmaqdır. Sol kənarda üç ulduzu qoyun:","en":"Sanrensei means taking three star points in a row along one side: the two corner stars and the side star between them. The aim is large influence and potential territory on that side. Place the three stars on the left side:","ru":"Санрэнсэй — занять три звёздные точки вдоль одной стороны: две угловые и боковую между ними. Цель — большое влияние и потенциальная территория на этой стороне. Поставьте три звезды на левой стороне:"},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"place","points":[60,174,288]},"hint":{"az":"Sol kənardan 4-cü xətt: yuxarı, orta, aşağı.","en":"4th line from the left: top, middle, bottom.","ru":"4-я линия слева: верх, середина, низ."},"success":{"az":"Sanrensei hazırdır.","en":"Sanrensei complete.","ru":"Санрэнсэй готов."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('open-tengen', 104, 2, 'openings', '{"az":"Tengen (mərkəz)","en":"Tengen (the centre)","ru":"Тэнгэн (центр)"}'::jsonb, '{"az":"Taxtanın tam mərkəzi.","en":"The exact centre point.","ru":"Точный центр доски."}'::jsonb, '[{"text":{"az":"Tengen — taxtanın tam mərkəzi nöqtəsidir (19×19-da 10-10). Mərkəzlə başlamaq nadir və iddialı açılışdır.","en":"Tengen is the exact centre point of the board (K10 on 19×19). Opening in the centre is rare and ambitious.","ru":"Тэнгэн — точный центр доски (K10 на 19×19). Начинать с центра — редкий и амбициозный дебют."},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"point","points":[180]},"success":{"az":"Düzdür — tengen.","en":"Correct — tengen.","ru":"Верно — тэнгэн."}}}]'::jsonb) on conflict (slug) do nothing;
insert into public.lessons (slug, position, level, track, title, summary, steps) values ('open-handicap', 105, 2, 'openings', '{"az":"Handikap daşları","en":"Handicap stones","ru":"Камни форы"}'::jsonb, '{"az":"4 daşlı handikap künc ulduzlarına qoyulur.","en":"A 4-stone handicap goes on the corner stars.","ru":"Фора в 4 камня ставится на угловые звёзды."}'::jsonb, '[{"text":{"az":"Handikap oyununda zəif oyunçu qara ilə əvvəlcədən daş qoyur, ağ isə birinci gedir. 4 daşlıq handikapda daşlar 4 küncün ulduz nöqtələrinə qoyulur. Onları yerləşdirin:","en":"In a handicap game the weaker player (Black) starts with extra stones and White moves first. A 4-stone handicap goes on the four corner star points. Place them:","ru":"В партии с форой более слабый игрок (чёрные) заранее ставит камни, а белые ходят первыми. Четыре камня форы ставятся на четыре угловые звезды. Расставьте их:"},"exercise":{"size":19,"rows":["...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","...................","..................."],"goal":{"type":"place","points":[60,72,288,300]},"success":{"az":"Bu, GO PLAY-in 4 daşlıq handikapı ilə eynidir.","en":"This matches GO PLAY’s 4-stone handicap.","ru":"Это совпадает с форой в 4 камня в GO PLAY."}}}]'::jsonb) on conflict (slug) do nothing;
